def verify_webhook_signature(secret=None, body=None, headers=None):
    """
    Checks if the webhook you received was sent by Filestack,
    based on your secret for the webhook endpoint which was generated in the Filestack developer portal.
    The body is supposed to be the raw content of the received webhook.

    Returns:
        Tuple: (bool, dict)

    Example:
        from filestack import Client

        result, details = verify_webhook_signature(
            'secret', b'{"webhook_content": "received_from_filestack"}',
            {'FS-Timestamp': '1558367878', 'FS-Signature': 'filestack-signature'}
        )
        Positive verification result: True, {}
        Negative verification result: False, {'error': 'error details'}
    """
    try:
        VerificationArguments.check({
            'secret': secret, 'body': body, 'headers': headers
        })
    except t.DataError as e:
        return False, {'error': str(e.as_dict())}

    # Convert headers to lowercase keys for consistent access
    lowercase_headers = {k.lower(): v for k, v in headers.items()}

    # Ensure body is in string format for HMAC computation
    if isinstance(body, bytes):
        body = body.decode('utf-8')

    # Prepare HMAC data
    hmac_data = '{}.{}'.format(body, lowercase_headers['fs-timestamp'])
    signature = hmac.new(
        secret.encode('utf-8'),
        hmac_data.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()

    # Compare computed signature with the expected signature from headers
    expected = lowercase_headers['fs-signature']
    if signature != expected:
        return False, {'error': 'Signature mismatch! Expected: {}. Got: {}'.format(expected, signature)}

    return True, {}

